def compute(vars):
    net_income = vars["Net Income"]
    revenue = vars["Revenue"]
    multiplier = vars["100"]

    if revenue == 0:
        return None

    net_profit_margin = (net_income / revenue) * multiplier
    return {
        "value": net_profit_margin,
        "trace": {
            "Net Income": net_income,
            "Revenue": revenue,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
